import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.B5WAEDB7.js";const g=JSON.parse('{"title":"Aktionen","description":"Alle Aktionen, die ein Flow in ApptiveGrid ausführen kann.","frontmatter":{"title":"Aktionen","description":"Alle Aktionen, die ein Flow in ApptiveGrid ausführen kann."},"headers":[],"relativePath":"flows/aktionen.md","filePath":"flows/aktionen.md","lastUpdated":1786167924000}'),a={name:"flows/aktionen.md"};function s(o,e,l,u,d,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="aktionen" tabindex="-1">Aktionen <a class="header-anchor" href="#aktionen" aria-label="Permalink to &quot;Aktionen&quot;">​</a></h1><p><strong>Aktionen</strong> sind die Schritte, die ein Flow ausführt. Sie liegen im Editor im Reiter <strong>Aktionen</strong> mit dem Hinweis <em>Wähle eine Aktion aus, um deinen Flow zu erweitern</em>.</p><p>Ein Flow kann beliebig viele Aktionen enthalten, hintereinander oder verzweigt.</p><div class="tip custom-block"><p class="custom-block-title">Mit „Pro&quot; gekennzeichnete Aktionen</p><p>Einige Aktionen tragen im Editor die Kennzeichnung <strong>Pro</strong> und stehen nur im höchsten Tarif zur Verfügung. Sie sind unten entsprechend markiert.</p></div><hr><h2 id="mit-eigenen-daten-arbeiten" tabindex="-1">Mit eigenen Daten arbeiten <a class="header-anchor" href="#mit-eigenen-daten-arbeiten" aria-label="Permalink to &quot;Mit eigenen Daten arbeiten&quot;">​</a></h2><h3 id="eintrag-erstellen" tabindex="-1">Eintrag erstellen <a class="header-anchor" href="#eintrag-erstellen" aria-label="Permalink to &quot;Eintrag erstellen&quot;">​</a></h3><blockquote><p><em>Erstellt einen neuen Eintrag</em></p></blockquote><p>Legt einen Eintrag in einem Grid an. Die Feldwerte setzen Sie fest oder aus vorherigen Schritten.</p><p><strong>Geeignet für:</strong> Daten aus einem Formular in ein zweites Grid spiegeln, Protokolleinträge schreiben, Aufgaben erzeugen.</p><div class="warning custom-block"><p class="custom-block-title">Kann den eigenen Flow erneut auslösen</p><p>Schreibt eine Aktion in dasselbe Grid, auf das der Auslöser <em>Neuer Eintrag</em> hört, startet der Flow sich selbst — immer wieder. Schreiben Sie in ein anderes Grid oder wählen Sie einen präziseren Auslöser.</p></div><h3 id="eintrag-aktualisieren" tabindex="-1">Eintrag aktualisieren <a class="header-anchor" href="#eintrag-aktualisieren" aria-label="Permalink to &quot;Eintrag aktualisieren&quot;">​</a></h3><blockquote><p><em>Einen Eintrag mit neuen Werten aktualisieren</em></p></blockquote><p>Ändert Felder eines bestehenden Eintrags — üblicherweise des Eintrags aus dem Auslöser.</p><p><strong>Geeignet für:</strong> Status setzen, Bearbeitungszeitpunkt festhalten, berechnete Ergebnisse zurückschreiben.</p><h3 id="alle-eintrage-laden" tabindex="-1">Alle Einträge laden <a class="header-anchor" href="#alle-eintrage-laden" aria-label="Permalink to &quot;Alle Einträge laden&quot;">​</a></h3><blockquote><p><em>Lade alle Einträge eines Grids</em></p></blockquote><p>Holt die Einträge eines Grids als Liste in den Flow.</p><p><strong>Geeignet für:</strong> Sammelauswertungen, Serienmails, regelmäßige Berichte.</p><div class="tip custom-block"><p class="custom-block-title">Fast immer mit „Parallel&quot; kombiniert</p><p>Eine Liste allein bringt wenig. Erst der Helfer <a href="/flows/router-und-parallel">Parallel</a> führt die folgenden Schritte für jeden Eintrag einzeln aus.</p></div><hr><h2 id="nach-außen-kommunizieren" tabindex="-1">Nach außen kommunizieren <a class="header-anchor" href="#nach-außen-kommunizieren" aria-label="Permalink to &quot;Nach außen kommunizieren&quot;">​</a></h2><h3 id="e-mail" tabindex="-1">E-Mail <a class="header-anchor" href="#e-mail" aria-label="Permalink to &quot;E-Mail&quot;">​</a></h3><blockquote><p><em>Eine Mail senden</em></p></blockquote><p>Empfänger, Betreff und Text lassen sich frei zusammensetzen — mit festen Texten und Werten aus vorherigen Schritten.</p><p><strong>Geeignet für:</strong> Bestätigungen, Benachrichtigungen, Erinnerungen, Weiterleitungen.</p><h3 id="http-anfrage" tabindex="-1">HTTP-Anfrage <a class="header-anchor" href="#http-anfrage" aria-label="Permalink to &quot;HTTP-Anfrage&quot;">​</a></h3><blockquote><p><em>Eine beliebige HTTP-Anfrage senden</em></p></blockquote><p>Die allgemeine Aktion für alles, wofür es keine fertige Integration gibt. Sie geben URL, Methode, Kopfzeilen und Inhalt selbst an.</p><p><strong>Geeignet für:</strong> eigene Systeme, Werkzeuge mit offener Schnittstelle, Automatisierungsdienste.</p><h3 id="slack-·-ms-teams-·-firebase-cloud-messaging" tabindex="-1">Slack · MS Teams · Firebase Cloud Messaging <a class="header-anchor" href="#slack-·-ms-teams-·-firebase-cloud-messaging" aria-label="Permalink to &quot;Slack · MS Teams · Firebase Cloud Messaging&quot;">​</a></h3><p>Fertige Aktionen zum Versand einer Nachricht in den jeweiligen Dienst.</p><h3 id="hubspot" tabindex="-1">Hubspot <a class="header-anchor" href="#hubspot" aria-label="Permalink to &quot;Hubspot&quot;">​</a></h3><p>Legt einen Kontakt im Hubspot-CRM an.</p><h3 id="magenta-business-sms-·-verify-·-verify-check-—-pro" tabindex="-1">Magenta Business SMS · Verify · Verify Check — <strong>Pro</strong> <a class="header-anchor" href="#magenta-business-sms-·-verify-·-verify-check-—-pro" aria-label="Permalink to &quot;Magenta Business SMS · Verify · Verify Check — **Pro**&quot;">​</a></h3><p>SMS versenden sowie Telefonnummern per SMS-Code bestätigen. <em>Verify</em> verschickt den Code, <em>Verify Check</em> prüft die Eingabe.</p><p><strong>Geeignet für:</strong> Zwei-Faktor-Bestätigung, Terminerinnerungen per SMS.</p><div class="warning custom-block"><p class="custom-block-title">Diese Dienste verlangen eigene Zugangsdaten</p><p>Für Slack, MS Teams, Firebase, Hubspot und Magenta Business brauchen Sie ein <strong>eigenes Konto</strong> beim jeweiligen Anbieter. Die Zugangsdaten tragen Sie im Flow-Schritt selbst ein — bei Slack und MS Teams eine Webhook-URL, bei Firebase einen API-Schlüssel, bei Hubspot ein API-Token, bei Magenta Schlüssel und Geheimnis.</p><p>Besorgen Sie diese, <strong>bevor</strong> Sie den Flow bauen. → <a href="/integrationen/ueberblick">Integrationen im Überblick</a></p></div><hr><h2 id="dateien-und-inhalte-erzeugen" tabindex="-1">Dateien und Inhalte erzeugen <a class="header-anchor" href="#dateien-und-inhalte-erzeugen" aria-label="Permalink to &quot;Dateien und Inhalte erzeugen&quot;">​</a></h2><h3 id="qr-code" tabindex="-1">QR Code <a class="header-anchor" href="#qr-code" aria-label="Permalink to &quot;QR Code&quot;">​</a></h3><blockquote><p><em>Erstellt einen QR Code</em></p></blockquote><p>Erzeugt einen QR-Code aus einem übergebenen Inhalt.</p><h3 id="pdf-zu-text-—-pro" tabindex="-1">PDF zu Text — <strong>Pro</strong> <a class="header-anchor" href="#pdf-zu-text-—-pro" aria-label="Permalink to &quot;PDF zu Text — **Pro**&quot;">​</a></h3><blockquote><p><em>PDF in Text umwandeln</em></p></blockquote><p>Liest den Textinhalt eines PDF aus.</p><p><strong>Geeignet für:</strong> eingehende Rechnungen oder Formulare maschinell auswerten.</p><h3 id="url-zu-pdf-—-pro" tabindex="-1">URL zu PDF — <strong>Pro</strong> <a class="header-anchor" href="#url-zu-pdf-—-pro" aria-label="Permalink to &quot;URL zu PDF — **Pro**&quot;">​</a></h3><blockquote><p><em>Webseite in PDF umwandeln</em></p></blockquote><p>Erzeugt aus einer Webadresse ein PDF.</p><div class="tip custom-block"><p class="custom-block-title">Belege und Bestätigungen erzeugen</p><p>In Kombination mit einer veröffentlichten <a href="/seiten/was-sind-seiten">Seite</a> lassen sich damit Bestätigungen und Belege als PDF erzeugen: Seite mit den Eintragsdaten aufrufen, in PDF wandeln, per E-Mail versenden.</p></div><h3 id="csv-datei-importieren" tabindex="-1">CSV-Datei importieren <a class="header-anchor" href="#csv-datei-importieren" aria-label="Permalink to &quot;CSV-Datei importieren&quot;">​</a></h3><blockquote><p><em>Importiert eine CSV-Datei</em></p></blockquote><p>Liest eine CSV-Datei von einer Adresse ein und stellt die Zeilen als Liste bereit.</p><h3 id="sprache-zu-text-—-pro" tabindex="-1">Sprache zu Text — <strong>Pro</strong> <a class="header-anchor" href="#sprache-zu-text-—-pro" aria-label="Permalink to &quot;Sprache zu Text — **Pro**&quot;">​</a></h3><blockquote><p><em>Audio in Text umwandeln</em></p></blockquote><p>Wandelt eine Audioaufnahme in Text um — etwa aus dem Block <em>Sprachaufnahme</em> eines Formulars.</p><h3 id="document-analyzer-—-pro" tabindex="-1">Document Analyzer — <strong>Pro</strong> <a class="header-anchor" href="#document-analyzer-—-pro" aria-label="Permalink to &quot;Document Analyzer — **Pro**&quot;">​</a></h3><p>Wertet Dokumente mit KI aus.</p><h3 id="kalendereintrag" tabindex="-1">Kalendereintrag <a class="header-anchor" href="#kalendereintrag" aria-label="Permalink to &quot;Kalendereintrag&quot;">​</a></h3><p>Erzeugt einen Kalendereintrag aus Titel, Beschreibung und Zeitangaben.</p><h3 id="datev-lohn-gehalt-—-pro" tabindex="-1">DATEV Lohn &amp; Gehalt — <strong>Pro</strong> <a class="header-anchor" href="#datev-lohn-gehalt-—-pro" aria-label="Permalink to &quot;DATEV Lohn &amp; Gehalt — **Pro**&quot;">​</a></h3><blockquote><p><em>Erstellt eine DATEV Import-Datei</em></p></blockquote><p>Erzeugt eine Importdatei für DATEV Lohn &amp; Gehalt.</p><div class="warning custom-block"><p class="custom-block-title">Zugangsdaten erforderlich</p><p>Diese Aktion verlangt Zugangsschlüssel und Passwort Ihres DATEV-Zugangs. Halten Sie diese bereit und behandeln Sie sie vertraulich.</p></div><hr><h2 id="mit-ki-arbeiten" tabindex="-1">Mit KI arbeiten <a class="header-anchor" href="#mit-ki-arbeiten" aria-label="Permalink to &quot;Mit KI arbeiten&quot;">​</a></h2><h3 id="openai-—-pro" tabindex="-1">OpenAI — <strong>Pro</strong> <a class="header-anchor" href="#openai-—-pro" aria-label="Permalink to &quot;OpenAI — **Pro**&quot;">​</a></h3><p>Schickt einen Prompt an ChatGPT und liefert die Antwort zurück.</p><p>Eingaben: <strong>Prompt</strong> und optional <strong>Zusätzliche Anweisungen</strong>.</p><p><strong>Geeignet für:</strong> Texte zusammenfassen, Rückmeldungen einordnen, Antwortentwürfe erzeugen.</p><div class="tip custom-block"><p class="custom-block-title">Kein eigener OpenAI-Vertrag nötig</p><p>Anders als bei den übrigen Integrationen brauchen Sie hier <strong>keinen</strong> eigenen Zugang und keinen API-Schlüssel. Der Schritt läuft über ApptiveGrid und ist einsatzbereit, sobald Ihr Tarif ihn enthält.</p></div><div class="danger custom-block"><p class="custom-block-title">Prüfen Sie, welche Daten Sie übergeben</p><p>Der Inhalt eines Prompts verlässt ApptiveGrid und wird an einen externen Dienst gesendet. Übergeben Sie keine personenbezogenen oder vertraulichen Daten ohne vorherige datenschutzrechtliche Prüfung.</p></div><h3 id="javascript" tabindex="-1">JavaScript <a class="header-anchor" href="#javascript" aria-label="Permalink to &quot;JavaScript&quot;">​</a></h3><blockquote><p><em>Führt JavaScript code aus</em></p></blockquote><p>Führt eigenen Code aus, wenn keine der fertigen Aktionen passt. Der Editor bietet:</p><ul><li>Eine Vorlage: <code>const data = input</code> … <code>return data</code></li><li><strong>Mit KI generieren</strong> — Beschreiben Sie in Worten, was der Code tun soll</li><li><strong>Vorherige Flow-Daten an KI senden</strong> — gibt der KI das Ergebnis des vorherigen Schritts als Kontext</li><li><strong>Vorherige Code-Version wiederherstellen</strong></li></ul><p>Schlägt die Erzeugung fehl, meldet der Editor <em>JavaScript konnte nicht generiert werden</em>.</p><div class="tip custom-block"><p class="custom-block-title">Der Schritt ist frei, die KI-Erzeugung nicht</p><p><strong>JavaScript ausführen</strong> steht in jedem Tarif zur Verfügung — Sie können also immer eigenen Code schreiben.</p><p>Tarifgebunden ist nur <strong>Mit KI generieren</strong>. Ohne diese Funktion tippen Sie den Code selbst, was für die meisten Umformungen ohnehin schneller geht als eine Beschreibung in Worten.</p></div><hr><h2 id="mit-menschen-interagieren" tabindex="-1">Mit Menschen interagieren <a class="header-anchor" href="#mit-menschen-interagieren" aria-label="Permalink to &quot;Mit Menschen interagieren&quot;">​</a></h2><h3 id="seite-anzeigen" tabindex="-1">Seite anzeigen <a class="header-anchor" href="#seite-anzeigen" aria-label="Permalink to &quot;Seite anzeigen&quot;">​</a></h3><blockquote><p><em>Zeigt eine Seite zur Nutzerinteraktion an</em></p></blockquote><p>Hält den Flow an und zeigt einer Person eine <a href="/seiten/was-sind-seiten">Seite</a>. Nach dem Absenden läuft der Flow weiter.</p><p><strong>Geeignet für:</strong> Genehmigungen, Rückfragen, mehrstufige Erfassung.</p><div class="warning custom-block"><p class="custom-block-title">Nicht mit dem gleichnamigen Auslöser verwechseln</p><p>Es gibt auch einen <strong>Auslöser</strong> namens <em>Seite anzeigen</em>. Der startet einen Flow, diese Aktion unterbricht ihn. Siehe <a href="/flows/trigger">Trigger</a>.</p></div><p>Fehlt einem Schritt die zugewiesene Seite, erscheint:</p><blockquote><p><em>Für diesen Schritt ist keine eigene UI hinterlegt. Falls du eine UI benötigst, kannst du sie im Flow Editor hinzufügen.</em></p></blockquote><h3 id="link-zu-seite-erstellen" tabindex="-1">Link zu Seite erstellen <a class="header-anchor" href="#link-zu-seite-erstellen" aria-label="Permalink to &quot;Link zu Seite erstellen&quot;">​</a></h3><blockquote><p><em>Erstellt einen Link zu einer Seite im Flow</em></p></blockquote><p>Erzeugt einen Link auf den aktuellen Durchlauf. Diesen Link können Sie per E-Mail verschicken, damit jemand später an dieser Stelle weitermacht.</p><div class="tip custom-block"><p class="custom-block-title">Der Weg zu asynchronen Prozessen</p><p><em>Seite anzeigen</em> setzt voraus, dass jemand gerade da ist. <em>Link zu Seite erstellen</em> in Kombination mit <em>E-Mail</em> funktioniert auch, wenn die Person erst morgen Zeit hat: Sie bekommt den Link zugeschickt und öffnet ihn, wann es passt.</p></div><h3 id="vorausgefullter-formularlink" tabindex="-1">Vorausgefüllter Formularlink <a class="header-anchor" href="#vorausgefullter-formularlink" aria-label="Permalink to &quot;Vorausgefüllter Formularlink&quot;">​</a></h3><blockquote><p><em>Aktualisiert einen Eintrag</em></p></blockquote><p>Erzeugt einen Link auf ein Formular, das den Eintrag bereits vorausgefüllt zur Bearbeitung öffnet.</p><p><strong>Geeignet für:</strong> Korrekturaufforderungen, Zu- und Absagen, Datenpflege durch Externe.</p><hr><h2 id="nichts-passendes-gefunden" tabindex="-1">Nichts Passendes gefunden? <a class="header-anchor" href="#nichts-passendes-gefunden" aria-label="Permalink to &quot;Nichts Passendes gefunden?&quot;">​</a></h2><p>Der Editor verweist selbst darauf: <em>Nichts passendes gefunden?</em> mit der Möglichkeit, eine Anfrage zu stellen.</p><p>Vorher lohnt der Blick auf <strong>HTTP-Anfrage</strong> — damit lassen sich die meisten Dienste anbinden, die eine offene Schnittstelle haben.</p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/referenz/flow-schritte">Flow-Schritte</a> — Kurzreferenz aller Schritte</li><li><a href="/flows/router-und-parallel">Router und Parallel</a></li><li><a href="/flows/daten-zwischen-schritten">Daten zwischen Schritten</a></li><li><a href="/flows/testen">Flows testen</a></li><li><a href="/integrationen/ueberblick">Integrationen im Überblick</a></li></ul>',102)])])}const p=n(a,[["render",s]]);export{g as __pageData,p as default};
